// Loading bar — fills left to right over the layer's duration.
// Everything outside the bar is fully transparent.
uniform float uHeight;     // @param 6 1 40
uniform float uMargin;     // @param 0 0 200
uniform float uBottom;     // @param 0 0 200
uniform vec3  uColor;      // @param #FFFFFF
uniform vec3  uTrackColor; // @param #FFFFFF
uniform float uTrackAlpha; // @param 0.2 0 1
uniform float uOpacity;    // @param 1 0 1

void main() {
  vec2 px = uv * iResolution;              // pixel coords, origin bottom-left
  float x0 = uMargin;
  float x1 = iResolution.x - uMargin;
  float y0 = uBottom;
  float y1 = uBottom + uHeight;

  // Antialiased coverage of the track rectangle
  float inX = smoothstep(x0 - 0.5, x0 + 0.5, px.x) * (1.0 - smoothstep(x1 - 0.5, x1 + 0.5, px.x));
  float inY = smoothstep(y0 - 0.5, y0 + 0.5, px.y) * (1.0 - smoothstep(y1 - 0.5, y1 + 0.5, px.y));
  float track = inX * inY;

  // Filled portion up to the progress edge
  float edge = mix(x0, x1, clamp(iProgress, 0.0, 1.0));
  float fill = track * (1.0 - smoothstep(edge - 0.5, edge + 0.5, px.x));

  float aTrack = track * uTrackAlpha * (1.0 - fill);
  float a = (fill + aTrack) * uOpacity;
  vec3 col = (uColor * fill + uTrackColor * aTrack) * uOpacity; // premultiplied

  fragColor = vec4(col, a);
}
